/* CommerceForge Dev Docs — Design System */

/* ── Reset & Base ──────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  /* OKLCH Color System */
  --bg-deep:     oklch(13% 0.015 260);
  --bg-base:     oklch(15% 0.018 260);
  --bg-surface:  oklch(19% 0.018 260);
  --bg-raised:   oklch(22% 0.018 260);
  --border:      oklch(28% 0.018 260);
  --border-subtle: oklch(24% 0.015 260);

  --accent:      oklch(78% 0.17 170);
  --accent-dim:  oklch(55% 0.12 170);
  --accent-bg:   oklch(22% 0.06 170);
  --accent-blue: oklch(65% 0.18 255);
  --accent-blue-dim: oklch(50% 0.12 255);

  --text:        oklch(95% 0.005 260);
  --text-secondary: oklch(68% 0.012 260);
  --text-muted:  oklch(50% 0.012 260);

  /* Typography */
  --font-sans: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', ui-monospace, monospace;

  /* Spacing Scale */
  --sp-1: 4px;  --sp-2: 8px;  --sp-3: 12px;  --sp-4: 16px;
  --sp-5: 20px; --sp-6: 24px; --sp-7: 32px;  --sp-8: 40px;
  --sp-9: 48px; --sp-10: 64px; --sp-11: 80px; --sp-12: 96px;

  /* Radius */
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;

  /* Transitions */
  --ease: cubic-bezier(0.4, 0, 0.2, 1);
  --duration: 200ms;

  /* Layout */
  --max-width: 1200px;
  --sidebar-width: 260px;
  --nav-height: 60px;
}

html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; }

body {
  font-family: var(--font-sans);
  background: var(--bg-deep);
  color: var(--text);
  line-height: 1.6;
  font-size: 15px;
  min-height: 100vh;
}

a { color: var(--accent); text-decoration: none; transition: color var(--duration) var(--ease); }
a:hover { color: oklch(85% 0.2 170); }

h1, h2, h3, h4 { line-height: 1.2; font-weight: 700; color: var(--text); }
h1 { font-size: clamp(2rem, 4vw, 2.75rem); letter-spacing: -0.03em; }
h2 { font-size: clamp(1.5rem, 3vw, 2rem); letter-spacing: -0.02em; }
h3 { font-size: 1.15rem; letter-spacing: -0.01em; }
h4 { font-size: 1rem; }

/* ── Top Navigation ────────────────────────────────────── */
.top-nav {
  position: sticky; top: 0; z-index: 100;
  height: var(--nav-height);
  background: oklch(13% 0.015 260 / 0.85);
  backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border-subtle);
  display: flex; align-items: center;
  padding: 0 var(--sp-6);
}

.nav-inner {
  max-width: var(--max-width);
  width: 100%;
  margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between;
}

.nav-brand {
  font-weight: 800; font-size: 1.05rem;
  color: var(--text);
  display: flex; align-items: center; gap: var(--sp-2);
  white-space: nowrap;
}

.nav-brand .brand-icon {
  width: 24px; height: 24px;
  background: var(--accent);
  border-radius: var(--radius-sm);
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 14px; font-weight: 900; color: var(--bg-deep);
}

.nav-links {
  display: flex; align-items: center; gap: var(--sp-6);
  list-style: none;
}

.nav-links a {
  color: var(--text-secondary);
  font-size: 0.9rem;
  font-weight: 500;
  transition: color var(--duration) var(--ease);
  padding: var(--sp-2) 0;
  position: relative;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--text);
}

.nav-links a.active::after {
  content: '';
  position: absolute; bottom: -2px; left: 0; right: 0;
  height: 2px;
  background: var(--accent);
  border-radius: 1px;
}

.nav-utils {
  display: flex; align-items: center; gap: var(--sp-4);
}

.nav-utils .search-btn {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  color: var(--text-muted);
  padding: var(--sp-1) var(--sp-3);
  font-size: 0.82rem;
  cursor: pointer;
  display: flex; align-items: center; gap: var(--sp-2);
  transition: border-color var(--duration) var(--ease);
}

.nav-utils .search-btn:hover { border-color: var(--accent-dim); }

.nav-utils .search-btn kbd {
  background: var(--bg-raised);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 1px 5px;
  font-family: var(--font-mono);
  font-size: 0.72rem;
  color: var(--text-muted);
}

.login-btn {
  color: var(--text-secondary) !important;
  font-size: 0.9rem !important;
  font-weight: 500 !important;
}

.mobile-menu-btn {
  display: none;
  background: none; border: none; color: var(--text); cursor: pointer;
  padding: var(--sp-2);
}

/* ── Page Layout ───────────────────────────────────────── */
.page-container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--sp-6);
}

.page-container.wide {
  max-width: 1400px;
}

/* Layout with sidebar */
.layout-with-sidebar {
  display: flex;
  max-width: 1400px;
  margin: 0 auto;
  min-height: calc(100vh - var(--nav-height));
}

.sidebar {
  width: var(--sidebar-width);
  flex-shrink: 0;
  border-right: 1px solid var(--border-subtle);
  padding: var(--sp-6) var(--sp-4);
  position: sticky;
  top: var(--nav-height);
  height: calc(100vh - var(--nav-height));
  overflow-y: auto;
  transition: width var(--duration) var(--ease), padding var(--duration) var(--ease);
}

.sidebar.collapsed {
  width: 0;
  padding: var(--sp-6) 0;
  overflow: hidden;
  border-right: none;
}

.sidebar-toggle {
  position: absolute;
  right: -14px;
  top: var(--sp-8);
  width: 28px; height: 28px;
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: 50%;
  color: var(--text-secondary);
  cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  font-size: 14px;
  z-index: 10;
  transition: all var(--duration) var(--ease);
}

.sidebar-toggle:hover {
  background: var(--bg-raised);
  color: var(--text);
  border-color: var(--accent-dim);
}

.sidebar-nav { list-style: none; }

.sidebar-nav li a {
  display: block;
  padding: var(--sp-2) var(--sp-3);
  color: var(--text-secondary);
  font-size: 0.88rem;
  border-radius: var(--radius-sm);
  transition: all var(--duration) var(--ease);
  margin-bottom: 2px;
}

.sidebar-nav li a:hover {
  color: var(--text);
  background: var(--bg-surface);
}

.sidebar-nav li a.active {
  color: var(--accent);
  background: var(--accent-bg);
}

.sidebar-label {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  padding: var(--sp-3) var(--sp-3) var(--sp-1);
  font-weight: 600;
}

.main-content {
  flex: 1;
  min-width: 0;
  padding: var(--sp-8) var(--sp-8) var(--sp-12);
}

/* ── Hero Section ──────────────────────────────────────── */
.hero {
  padding: var(--sp-12) 0 var(--sp-10);
  max-width: 720px;
}

.hero.narrow { max-width: 600px; }

.hero h1 {
  margin-bottom: var(--sp-4);
  background: linear-gradient(135deg, var(--text) 0%, var(--text-secondary) 100%);
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero p {
  font-size: 1.08rem;
  color: var(--text-secondary);
  line-height: 1.7;
  margin-bottom: var(--sp-6);
}

.hero-ctas {
  display: flex; flex-wrap: wrap; gap: var(--sp-3);
}

/* ── Buttons ───────────────────────────────────────────── */
.btn {
  display: inline-flex; align-items: center; gap: var(--sp-2);
  padding: var(--sp-2) var(--sp-5);
  border-radius: var(--radius-md);
  font-family: var(--font-sans);
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: all var(--duration) var(--ease);
  white-space: nowrap;
}

.btn-primary {
  background: var(--accent);
  color: var(--bg-deep);
}

.btn-primary:hover {
  background: oklch(82% 0.19 170);
  color: var(--bg-deep);
}

.btn-secondary {
  background: var(--bg-surface);
  color: var(--text);
  border: 1px solid var(--border);
}

.btn-secondary:hover {
  border-color: var(--accent-dim);
  background: var(--bg-raised);
}

.btn-ghost {
  background: transparent;
  color: var(--accent);
  padding: var(--sp-2) var(--sp-3);
}

.btn-ghost:hover {
  background: var(--accent-bg);
}

.btn-arrow::after {
  content: '→';
  transition: transform var(--duration) var(--ease);
}

.btn-arrow:hover::after {
  transform: translateX(3px);
}

/* ── Cards ─────────────────────────────────────────────── */
.card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: var(--sp-6);
  transition: all var(--duration) var(--ease);
  position: relative;
}

.card:hover {
  border-color: var(--border);
  transform: translateY(-2px);
  box-shadow: 0 8px 32px oklch(0% 0 0 / 0.3);
}

.card-icon {
  width: 40px; height: 40px;
  border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  font-size: 1.2rem;
  margin-bottom: var(--sp-4);
}

.card-icon.green { background: oklch(25% 0.06 170); color: var(--accent); }
.card-icon.blue { background: oklch(22% 0.06 255); color: var(--accent-blue); }
.card-icon.purple { background: oklch(22% 0.06 300); color: oklch(72% 0.16 300); }
.card-icon.orange { background: oklch(25% 0.07 60); color: oklch(75% 0.16 60); }
.card-icon.red { background: oklch(22% 0.06 20); color: oklch(68% 0.16 20); }
.card-icon.cyan { background: oklch(22% 0.06 195); color: oklch(72% 0.14 195); }

.card h3 {
  margin-bottom: var(--sp-2);
  font-size: 1.05rem;
}

.card p {
  color: var(--text-secondary);
  font-size: 0.9rem;
  line-height: 1.6;
  margin-bottom: var(--sp-4);
}

.card .card-cta {
  font-size: 0.88rem;
  font-weight: 600;
}

/* Cards grid */
.cards-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--sp-5);
}

.cards-grid-3 {
  grid-template-columns: repeat(3, 1fr);
}

.cards-grid-2 {
  grid-template-columns: repeat(2, 1fr);
}

/* ── Product Cards (Home) ──────────────────────────────── */
.product-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--sp-5);
  margin-bottom: var(--sp-12);
}

.product-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: var(--sp-7);
  transition: all var(--duration) var(--ease);
  position: relative;
  overflow: hidden;
}

.product-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  border-radius: var(--radius-lg) var(--radius-lg) 0 0;
}

.product-card.apps::before { background: var(--accent); }
.product-card.storefronts::before { background: var(--accent-blue); }
.product-card.agents::before { background: oklch(72% 0.16 300); }

.product-card:hover {
  border-color: var(--border);
  transform: translateY(-3px);
  box-shadow: 0 12px 40px oklch(0% 0 0 / 0.35);
}

.product-card .product-label {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 700;
  margin-bottom: var(--sp-3);
}

.product-card.apps .product-label { color: var(--accent); }
.product-card.storefronts .product-label { color: var(--accent-blue); }
.product-card.agents .product-label { color: oklch(72% 0.16 300); }

.product-card h3 {
  font-size: 1.25rem;
  margin-bottom: var(--sp-3);
}

.product-card p {
  color: var(--text-secondary);
  font-size: 0.92rem;
  line-height: 1.65;
  margin-bottom: var(--sp-5);
}

.product-card .card-cta {
  font-weight: 600; font-size: 0.9rem;
}

.product-card.apps .card-cta { color: var(--accent); }
.product-card.storefronts .card-cta { color: var(--accent-blue); }
.product-card.agents .card-cta { color: oklch(72% 0.16 300); }

/* ── CLI / Accordion Section ───────────────────────────── */
.cli-section {
  margin-bottom: var(--sp-12);
}

.cli-section > h2 {
  margin-bottom: var(--sp-3);
}

.cli-section > p {
  color: var(--text-secondary);
  max-width: 640px;
  line-height: 1.7;
  margin-bottom: var(--sp-7);
}

.accordion {
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--bg-surface);
}

.accordion-item {
  border-bottom: 1px solid var(--border-subtle);
}

.accordion-item:last-child { border-bottom: none; }

.accordion-header {
  width: 100%;
  background: none; border: none;
  color: var(--text);
  padding: var(--sp-4) var(--sp-5);
  font-family: var(--font-sans);
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  display: flex; align-items: center; justify-content: space-between;
  transition: background var(--duration) var(--ease);
}

.accordion-header:hover {
  background: var(--bg-raised);
}

.accordion-header .chevron {
  transition: transform var(--duration) var(--ease);
  color: var(--text-muted);
  font-size: 0.8rem;
}

.accordion-item.open .accordion-header .chevron {
  transform: rotate(180deg);
}

.accordion-item.open .accordion-header {
  color: var(--accent);
}

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 300ms var(--ease);
}

.accordion-body-inner {
  padding: 0 var(--sp-5) var(--sp-5);
}

.step-list {
  list-style: none;
  counter-reset: steps;
}

.step-list li {
  counter-increment: steps;
  padding: var(--sp-3) 0;
  color: var(--text-secondary);
  font-size: 0.9rem;
  display: flex; gap: var(--sp-3);
  line-height: 1.6;
}

.step-list li::before {
  content: counter(steps);
  min-width: 24px; height: 24px;
  background: var(--accent-bg);
  color: var(--accent);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 0.75rem;
  font-weight: 700;
  flex-shrink: 0;
  margin-top: 2px;
}

/* Tabbed code blocks */
.code-tabs {
  margin-top: var(--sp-4);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
}

.code-tabs-header {
  display: flex;
  background: var(--bg-raised);
  border-bottom: 1px solid var(--border-subtle);
}

.code-tab {
  padding: var(--sp-2) var(--sp-4);
  background: none; border: none;
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 0.82rem;
  cursor: pointer;
  position: relative;
  transition: color var(--duration) var(--ease);
}

.code-tab:hover { color: var(--text-secondary); }

.code-tab.active {
  color: var(--accent);
}

.code-tab.active::after {
  content: '';
  position: absolute; bottom: 0; left: 0; right: 0;
  height: 2px;
  background: var(--accent);
}

.code-panel {
  display: none;
  padding: var(--sp-4);
}

.code-panel.active { display: block; }

.code-block {
  background: var(--bg-deep);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: var(--sp-4) var(--sp-5);
  font-family: var(--font-mono);
  font-size: 0.88rem;
  line-height: 1.7;
  color: var(--text);
  overflow-x: auto;
  margin-top: var(--sp-3);
}

.code-block .prompt { color: var(--accent); user-select: none; }
.code-block .flag { color: oklch(72% 0.16 300); }
.code-block .pkg { color: var(--accent-blue); }

/* ── Launch CTA Section ────────────────────────────────── */
.launch-section {
  margin-bottom: var(--sp-12);
}

.launch-cards {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--sp-5);
}

.launch-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: var(--sp-7);
  transition: all var(--duration) var(--ease);
}

.launch-card:hover {
  border-color: var(--border);
}

.launch-card h3 { margin-bottom: var(--sp-3); }

.launch-card p {
  color: var(--text-secondary);
  font-size: 0.92rem;
  line-height: 1.65;
  margin-bottom: var(--sp-4);
}

/* ── Community Section ─────────────────────────────────── */
.community-section {
  margin-bottom: var(--sp-12);
}

.community-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--sp-4);
}

.community-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: var(--sp-5);
  transition: all var(--duration) var(--ease);
}

.community-card:hover {
  border-color: var(--border);
  transform: translateY(-1px);
}

.community-card h4 {
  margin-bottom: var(--sp-2);
  font-size: 0.92rem;
}

.community-card h4 a { color: var(--accent); }

.community-card p {
  color: var(--text-muted);
  font-size: 0.82rem;
  line-height: 1.5;
}

/* ── Section Headers ───────────────────────────────────── */
.section-header {
  margin-bottom: var(--sp-6);
}

.section-header h2 {
  margin-bottom: var(--sp-2);
}

.section-header p {
  color: var(--text-secondary);
  max-width: 600px;
  line-height: 1.7;
}

/* ── Surfaces / Building Blocks / Use Cases Grids ──────── */
.surface-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: var(--sp-5);
  transition: all var(--duration) var(--ease);
}

.surface-card:hover {
  border-color: var(--border);
}

.surface-card h4 { margin-bottom: var(--sp-2); }

.surface-card p {
  color: var(--text-secondary);
  font-size: 0.85rem;
  line-height: 1.55;
}

/* ── Best Practices ────────────────────────────────────── */
.practices-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: var(--sp-4);
}

.practice-item {
  display: flex; align-items: flex-start; gap: var(--sp-3);
  padding: var(--sp-4);
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
}

.practice-item .practice-icon {
  width: 28px; height: 28px;
  background: var(--accent-bg);
  color: var(--accent);
  border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
  font-size: 0.85rem;
}

.practice-item h4 {
  font-size: 0.9rem;
  margin-bottom: var(--sp-1);
}

.practice-item p {
  color: var(--text-muted);
  font-size: 0.8rem;
  line-height: 1.5;
}

/* ── Footer ────────────────────────────────────────────── */
.site-footer {
  border-top: 1px solid var(--border-subtle);
  padding: var(--sp-10) 0 var(--sp-8);
  margin-top: var(--sp-12);
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--sp-6);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: var(--sp-8);
  margin-bottom: var(--sp-8);
}

.footer-brand {
  font-weight: 800;
  font-size: 1rem;
  margin-bottom: var(--sp-3);
  display: flex; align-items: center; gap: var(--sp-2);
}

.footer-brand .brand-icon {
  width: 20px; height: 20px;
  background: var(--accent);
  border-radius: 4px;
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 11px; font-weight: 900; color: var(--bg-deep);
}

.footer-brand p {
  color: var(--text-muted);
  font-size: 0.82rem;
  line-height: 1.6;
  max-width: 280px;
}

.footer-col h5 {
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  margin-bottom: var(--sp-3);
  font-weight: 600;
}

.footer-col ul {
  list-style: none;
}

.footer-col ul li {
  margin-bottom: var(--sp-2);
}

.footer-col ul li a {
  color: var(--text-secondary);
  font-size: 0.85rem;
}

.footer-col ul li a:hover {
  color: var(--text);
}

.footer-bottom {
  border-top: 1px solid var(--border-subtle);
  padding-top: var(--sp-5);
  display: flex; justify-content: space-between; align-items: center;
}

.footer-bottom p {
  color: var(--text-muted);
  font-size: 0.78rem;
}

/* ── Agents Protocol Diagram ───────────────────────────── */
.protocol-diagram {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--sp-4);
  margin: var(--sp-6) 0;
}

.protocol-actor {
  text-align: center;
  padding: var(--sp-5);
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
}

.protocol-actor .actor-icon {
  width: 48px; height: 48px;
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  margin: 0 auto var(--sp-3);
  font-size: 1.3rem;
  font-weight: 700;
}

.protocol-actor .actor-icon.agent { background: oklch(25% 0.06 170); color: var(--accent); }
.protocol-actor .actor-icon.merchant { background: oklch(22% 0.06 255); color: var(--accent-blue); }
.protocol-actor .actor-icon.cp { background: oklch(22% 0.06 300); color: oklch(72% 0.16 300); }
.protocol-actor .actor-icon.psp { background: oklch(25% 0.07 60); color: oklch(75% 0.16 60); }

.protocol-actor h4 { margin-bottom: var(--sp-1); font-size: 0.95rem; }
.protocol-actor p { color: var(--text-muted); font-size: 0.8rem; }

/* ── Status Badge ──────────────────────────────────────── */
.status-badge {
  display: inline-flex; align-items: center; gap: var(--sp-1);
  font-size: 0.75rem; font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 3px 10px;
  border-radius: 20px;
  background: oklch(25% 0.07 60 / 0.5);
  color: oklch(75% 0.16 60);
}

/* ── Support Cards ─────────────────────────────────────── */
.support-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--sp-4);
}

.support-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: var(--sp-5);
}

.support-card h4 {
  margin-bottom: var(--sp-2);
}

.support-card ul {
  list-style: none;
}

.support-card ul li {
  padding: var(--sp-1) 0;
  color: var(--text-secondary);
  font-size: 0.88rem;
}

.support-card ul li a { color: var(--text-secondary); }
.support-card ul li a:hover { color: var(--accent); }

/* ── Theme / Headless Sections ─────────────────────────── */
.split-section {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--sp-8);
  margin-bottom: var(--sp-10);
}

.feature-list {
  list-style: none;
}

.feature-list li {
  padding: var(--sp-3) 0;
  border-bottom: 1px solid var(--border-subtle);
  display: flex; gap: var(--sp-3);
  align-items: flex-start;
}

.feature-list li:last-child { border-bottom: none; }

.feature-list .feature-dot {
  width: 6px; height: 6px;
  background: var(--accent);
  border-radius: 50%;
  margin-top: 8px;
  flex-shrink: 0;
}

.feature-list h4 {
  font-size: 0.92rem;
  margin-bottom: var(--sp-1);
}

.feature-list p {
  color: var(--text-secondary);
  font-size: 0.85rem;
  line-height: 1.5;
}

/* ── Responsive ────────────────────────────────────────── */
@media (max-width: 1024px) {
  .product-cards { grid-template-columns: 1fr; }
  .cards-grid-3 { grid-template-columns: repeat(2, 1fr); }
  .community-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .protocol-diagram { grid-template-columns: repeat(2, 1fr); }
  .split-section { grid-template-columns: 1fr; gap: var(--sp-6); }
  .launch-cards { grid-template-columns: 1fr; }

  .sidebar {
    position: fixed;
    left: 0; top: var(--nav-height);
    z-index: 90;
    background: var(--bg-base);
    transform: translateX(-100%);
    transition: transform var(--duration) var(--ease);
    width: var(--sidebar-width);
    padding: var(--sp-6) var(--sp-4);
    height: calc(100vh - var(--nav-height));
  }

  .sidebar:not(.collapsed) {
    transform: translateX(0);
  }

  .sidebar.collapsed {
    width: var(--sidebar-width);
    padding: var(--sp-6) var(--sp-4);
    overflow: auto;
  }

  .sidebar-toggle {
    display: none;
  }
}

@media (max-width: 768px) {
  :root { --sp-6: 16px; --sp-8: 24px; --sp-12: 48px; }

  .nav-links { display: none; }
  .nav-links.open {
    display: flex; flex-direction: column;
    position: absolute; top: var(--nav-height); left: 0; right: 0;
    background: var(--bg-base);
    border-bottom: 1px solid var(--border);
    padding: var(--sp-4) var(--sp-6);
    gap: var(--sp-1);
  }

  .mobile-menu-btn { display: flex; }

  .cards-grid, .cards-grid-3, .cards-grid-2 { grid-template-columns: 1fr; }
  .community-grid { grid-template-columns: 1fr; }
  .launch-cards { grid-template-columns: 1fr; }
  .support-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: var(--sp-5); }
  .protocol-diagram { grid-template-columns: 1fr 1fr; }
  .hero { padding: var(--sp-8) 0 var(--sp-6); }

  .main-content {
    padding: var(--sp-5) var(--sp-4) var(--sp-8);
  }
}

@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
  .protocol-diagram { grid-template-columns: 1fr; }
  .hero-ctas { flex-direction: column; }
  .hero-ctas .btn { width: 100%; justify-content: center; }
}

/* ── Utility ───────────────────────────────────────────── */
.mt-4 { margin-top: var(--sp-4); }
.mt-6 { margin-top: var(--sp-6); }
.mt-8 { margin-top: var(--sp-8); }
.mb-4 { margin-bottom: var(--sp-4); }
.mb-6 { margin-bottom: var(--sp-6); }
.mb-8 { margin-bottom: var(--sp-8); }
.mb-10 { margin-bottom: var(--sp-10); }
.mb-12 { margin-bottom: var(--sp-12); }

.text-accent { color: var(--accent); }
.text-blue { color: var(--accent-blue); }
.text-muted { color: var(--text-muted); }
.text-secondary { color: var(--text-secondary); }

/* CommerceForge Dev Docs — Design System */

/* ── Reset & Base ──────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  /* OKLCH Color System */
  --bg-deep:     oklch(13% 0.015 260);
  --bg-base:     oklch(15% 0.018 260);
  --bg-surface:  oklch(19% 0.018 260);
  --bg-raised:   oklch(22% 0.018 260);
  --border:      oklch(28% 0.018 260);
  --border-subtle: oklch(24% 0.015 260);

  --accent:      oklch(78% 0.17 170);
  --accent-dim:  oklch(55% 0.12 170);
  --accent-bg:   oklch(22% 0.06 170);
  --accent-blue: oklch(65% 0.18 255);
  --accent-blue-dim: oklch(50% 0.12 255);

  --text:        oklch(95% 0.005 260);
  --text-secondary: oklch(68% 0.012 260);
  --text-muted:  oklch(50% 0.012 260);

  /* Typography */
  --font-sans: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', ui-monospace, monospace;

  /* Spacing Scale */
  --sp-1: 4px;  --sp-2: 8px;  --sp-3: 12px;  --sp-4: 16px;
  --sp-5: 20px; --sp-6: 24px; --sp-7: 32px;  --sp-8: 40px;
  --sp-9: 48px; --sp-10: 64px; --sp-11: 80px; --sp-12: 96px;

  /* Radius */
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;

  /* Transitions */
  --ease: cubic-bezier(0.4, 0, 0.2, 1);
  --duration: 200ms;

  /* Layout */
  --max-width: 1200px;
  --sidebar-width: 260px;
  --nav-height: 60px;
}

html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; }

body {
  font-family: var(--font-sans);
  background: var(--bg-deep);
  color: var(--text);
  line-height: 1.6;
  font-size: 15px;
  min-height: 100vh;
}

a { color: var(--accent); text-decoration: none; transition: color var(--duration) var(--ease); }
a:hover { color: oklch(85% 0.2 170); }

h1, h2, h3, h4 { line-height: 1.2; font-weight: 700; color: var(--text); }
h1 { font-size: clamp(2rem, 4vw, 2.75rem); letter-spacing: -0.03em; }
h2 { font-size: clamp(1.5rem, 3vw, 2rem); letter-spacing: -0.02em; }
h3 { font-size: 1.15rem; letter-spacing: -0.01em; }
h4 { font-size: 1rem; }

/* ── Top Navigation ────────────────────────────────────── */
.top-nav {
  position: sticky; top: 0; z-index: 100;
  height: var(--nav-height);
  background: oklch(13% 0.015 260 / 0.85);
  backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border-subtle);
  display: flex; align-items: center;
  padding: 0 var(--sp-6);
}

.nav-inner {
  max-width: var(--max-width);
  width: 100%;
  margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between;
}

.nav-brand {
  font-weight: 800; font-size: 1.05rem;
  color: var(--text);
  display: flex; align-items: center; gap: var(--sp-2);
  white-space: nowrap;
}

.nav-brand .brand-icon {
  width: 24px; height: 24px;
  background: var(--accent);
  border-radius: var(--radius-sm);
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 14px; font-weight: 900; color: var(--bg-deep);
}

.nav-links {
  display: flex; align-items: center; gap: var(--sp-6);
  list-style: none;
}

.nav-links a {
  color: var(--text-secondary);
  font-size: 0.9rem;
  font-weight: 500;
  transition: color var(--duration) var(--ease);
  padding: var(--sp-2) 0;
  position: relative;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--text);
}

.nav-links a.active::after {
  content: '';
  position: absolute; bottom: -2px; left: 0; right: 0;
  height: 2px;
  background: var(--accent);
  border-radius: 1px;
}

.nav-utils {
  display: flex; align-items: center; gap: var(--sp-4);
}

.nav-utils .search-btn {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  color: var(--text-muted);
  padding: var(--sp-1) var(--sp-3);
  font-size: 0.82rem;
  cursor: pointer;
  display: flex; align-items: center; gap: var(--sp-2);
  transition: border-color var(--duration) var(--ease);
}

.nav-utils .search-btn:hover { border-color: var(--accent-dim); }

.nav-utils .search-btn kbd {
  background: var(--bg-raised);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 1px 5px;
  font-family: var(--font-mono);
  font-size: 0.72rem;
  color: var(--text-muted);
}

.login-btn {
  color: var(--text-secondary) !important;
  font-size: 0.9rem !important;
  font-weight: 500 !important;
}

.mobile-menu-btn {
  display: none;
  background: none; border: none; color: var(--text); cursor: pointer;
  padding: var(--sp-2);
}

/* ── Page Layout ───────────────────────────────────────── */
.page-container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--sp-6);
}

.page-container.wide {
  max-width: 1400px;
}

/* Layout with sidebar */
.layout-with-sidebar {
  display: flex;
  max-width: 1400px;
  margin: 0 auto;
  min-height: calc(100vh - var(--nav-height));
}

.sidebar {
  width: var(--sidebar-width);
  flex-shrink: 0;
  border-right: 1px solid var(--border-subtle);
  padding: var(--sp-6) var(--sp-4);
  position: sticky;
  top: var(--nav-height);
  height: calc(100vh - var(--nav-height));
  overflow-y: auto;
  transition: width var(--duration) var(--ease), padding var(--duration) var(--ease);
}

.sidebar.collapsed {
  width: 0;
  padding: var(--sp-6) 0;
  overflow: hidden;
  border-right: none;
}

.sidebar-toggle {
  position: absolute;
  right: -14px;
  top: var(--sp-8);
  width: 28px; height: 28px;
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: 50%;
  color: var(--text-secondary);
  cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  font-size: 14px;
  z-index: 10;
  transition: all var(--duration) var(--ease);
}

.sidebar-toggle:hover {
  background: var(--bg-raised);
  color: var(--text);
  border-color: var(--accent-dim);
}

.sidebar-nav { list-style: none; }

.sidebar-nav li a {
  display: block;
  padding: var(--sp-2) var(--sp-3);
  color: var(--text-secondary);
  font-size: 0.88rem;
  border-radius: var(--radius-sm);
  transition: all var(--duration) var(--ease);
  margin-bottom: 2px;
}

.sidebar-nav li a:hover {
  color: var(--text);
  background: var(--bg-surface);
}

.sidebar-nav li a.active {
  color: var(--accent);
  background: var(--accent-bg);
}

.sidebar-label {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  padding: var(--sp-3) var(--sp-3) var(--sp-1);
  font-weight: 600;
}

.main-content {
  flex: 1;
  min-width: 0;
  padding: var(--sp-8) var(--sp-8) var(--sp-12);
}

/* ── Hero Section ──────────────────────────────────────── */
.hero {
  padding: var(--sp-12) 0 var(--sp-10);
  max-width: 720px;
}

.hero.narrow { max-width: 600px; }

.hero h1 {
  margin-bottom: var(--sp-4);
  background: linear-gradient(135deg, var(--text) 0%, var(--text-secondary) 100%);
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero p {
  font-size: 1.08rem;
  color: var(--text-secondary);
  line-height: 1.7;
  margin-bottom: var(--sp-6);
}

.hero-ctas {
  display: flex; flex-wrap: wrap; gap: var(--sp-3);
}

/* ── Buttons ───────────────────────────────────────────── */
.btn {
  display: inline-flex; align-items: center; gap: var(--sp-2);
  padding: var(--sp-2) var(--sp-5);
  border-radius: var(--radius-md);
  font-family: var(--font-sans);
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: all var(--duration) var(--ease);
  white-space: nowrap;
}

.btn-primary {
  background: var(--accent);
  color: var(--bg-deep);
}

.btn-primary:hover {
  background: oklch(82% 0.19 170);
  color: var(--bg-deep);
}

.btn-secondary {
  background: var(--bg-surface);
  color: var(--text);
  border: 1px solid var(--border);
}

.btn-secondary:hover {
  border-color: var(--accent-dim);
  background: var(--bg-raised);
}

.btn-ghost {
  background: transparent;
  color: var(--accent);
  padding: var(--sp-2) var(--sp-3);
}

.btn-ghost:hover {
  background: var(--accent-bg);
}

.btn-arrow::after {
  content: '→';
  transition: transform var(--duration) var(--ease);
}

.btn-arrow:hover::after {
  transform: translateX(3px);
}

/* ── Cards ─────────────────────────────────────────────── */
.card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: var(--sp-6);
  transition: all var(--duration) var(--ease);
  position: relative;
}

.card:hover {
  border-color: var(--border);
  transform: translateY(-2px);
  box-shadow: 0 8px 32px oklch(0% 0 0 / 0.3);
}

.card-icon {
  width: 40px; height: 40px;
  border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  font-size: 1.2rem;
  margin-bottom: var(--sp-4);
}

.card-icon.green { background: oklch(25% 0.06 170); color: var(--accent); }
.card-icon.blue { background: oklch(22% 0.06 255); color: var(--accent-blue); }
.card-icon.purple { background: oklch(22% 0.06 300); color: oklch(72% 0.16 300); }
.card-icon.orange { background: oklch(25% 0.07 60); color: oklch(75% 0.16 60); }
.card-icon.red { background: oklch(22% 0.06 20); color: oklch(68% 0.16 20); }
.card-icon.cyan { background: oklch(22% 0.06 195); color: oklch(72% 0.14 195); }

.card h3 {
  margin-bottom: var(--sp-2);
  font-size: 1.05rem;
}

.card p {
  color: var(--text-secondary);
  font-size: 0.9rem;
  line-height: 1.6;
  margin-bottom: var(--sp-4);
}

.card .card-cta {
  font-size: 0.88rem;
  font-weight: 600;
}

/* Cards grid */
.cards-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--sp-5);
}

.cards-grid-3 {
  grid-template-columns: repeat(3, 1fr);
}

.cards-grid-2 {
  grid-template-columns: repeat(2, 1fr);
}

/* ── Product Cards (Home) ──────────────────────────────── */
.product-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--sp-5);
  margin-bottom: var(--sp-12);
}

.product-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: var(--sp-7);
  transition: all var(--duration) var(--ease);
  position: relative;
  overflow: hidden;
}

.product-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  border-radius: var(--radius-lg) var(--radius-lg) 0 0;
}

.product-card.apps::before { background: var(--accent); }
.product-card.storefronts::before { background: var(--accent-blue); }
.product-card.agents::before { background: oklch(72% 0.16 300); }

.product-card:hover {
  border-color: var(--border);
  transform: translateY(-3px);
  box-shadow: 0 12px 40px oklch(0% 0 0 / 0.35);
}

.product-card .product-label {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 700;
  margin-bottom: var(--sp-3);
}

.product-card.apps .product-label { color: var(--accent); }
.product-card.storefronts .product-label { color: var(--accent-blue); }
.product-card.agents .product-label { color: oklch(72% 0.16 300); }

.product-card h3 {
  font-size: 1.25rem;
  margin-bottom: var(--sp-3);
}

.product-card p {
  color: var(--text-secondary);
  font-size: 0.92rem;
  line-height: 1.65;
  margin-bottom: var(--sp-5);
}

.product-card .card-cta {
  font-weight: 600; font-size: 0.9rem;
}

.product-card.apps .card-cta { color: var(--accent); }
.product-card.storefronts .card-cta { color: var(--accent-blue); }
.product-card.agents .card-cta { color: oklch(72% 0.16 300); }

/* ── CLI / Accordion Section ───────────────────────────── */
.cli-section {
  margin-bottom: var(--sp-12);
}

.cli-section > h2 {
  margin-bottom: var(--sp-3);
}

.cli-section > p {
  color: var(--text-secondary);
  max-width: 640px;
  line-height: 1.7;
  margin-bottom: var(--sp-7);
}

.accordion {
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--bg-surface);
}

.accordion-item {
  border-bottom: 1px solid var(--border-subtle);
}

.accordion-item:last-child { border-bottom: none; }

.accordion-header {
  width: 100%;
  background: none; border: none;
  color: var(--text);
  padding: var(--sp-4) var(--sp-5);
  font-family: var(--font-sans);
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  display: flex; align-items: center; justify-content: space-between;
  transition: background var(--duration) var(--ease);
}

.accordion-header:hover {
  background: var(--bg-raised);
}

.accordion-header .chevron {
  transition: transform var(--duration) var(--ease);
  color: var(--text-muted);
  font-size: 0.8rem;
}

.accordion-item.open .accordion-header .chevron {
  transform: rotate(180deg);
}

.accordion-item.open .accordion-header {
  color: var(--accent);
}

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 300ms var(--ease);
}

.accordion-body-inner {
  padding: 0 var(--sp-5) var(--sp-5);
}

.step-list {
  list-style: none;
  counter-reset: steps;
}

.step-list li {
  counter-increment: steps;
  padding: var(--sp-3) 0;
  color: var(--text-secondary);
  font-size: 0.9rem;
  display: flex; gap: var(--sp-3);
  line-height: 1.6;
}

.step-list li::before {
  content: counter(steps);
  min-width: 24px; height: 24px;
  background: var(--accent-bg);
  color: var(--accent);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 0.75rem;
  font-weight: 700;
  flex-shrink: 0;
  margin-top: 2px;
}

/* Tabbed code blocks */
.code-tabs {
  margin-top: var(--sp-4);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
}

.code-tabs-header {
  display: flex;
  background: var(--bg-raised);
  border-bottom: 1px solid var(--border-subtle);
}

.code-tab {
  padding: var(--sp-2) var(--sp-4);
  background: none; border: none;
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 0.82rem;
  cursor: pointer;
  position: relative;
  transition: color var(--duration) var(--ease);
}

.code-tab:hover { color: var(--text-secondary); }

.code-tab.active {
  color: var(--accent);
}

.code-tab.active::after {
  content: '';
  position: absolute; bottom: 0; left: 0; right: 0;
  height: 2px;
  background: var(--accent);
}

.code-panel {
  display: none;
  padding: var(--sp-4);
}

.code-panel.active { display: block; }

.code-block {
  background: var(--bg-deep);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: var(--sp-4) var(--sp-5);
  font-family: var(--font-mono);
  font-size: 0.88rem;
  line-height: 1.7;
  color: var(--text);
  overflow-x: auto;
  margin-top: var(--sp-3);
}

.code-block .prompt { color: var(--accent); user-select: none; }
.code-block .flag { color: oklch(72% 0.16 300); }
.code-block .pkg { color: var(--accent-blue); }

/* ── Launch CTA Section ────────────────────────────────── */
.launch-section {
  margin-bottom: var(--sp-12);
}

.launch-cards {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--sp-5);
}

.launch-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: var(--sp-7);
  transition: all var(--duration) var(--ease);
}

.launch-card:hover {
  border-color: var(--border);
}

.launch-card h3 { margin-bottom: var(--sp-3); }

.launch-card p {
  color: var(--text-secondary);
  font-size: 0.92rem;
  line-height: 1.65;
  margin-bottom: var(--sp-4);
}

/* ── Community Section ─────────────────────────────────── */
.community-section {
  margin-bottom: var(--sp-12);
}

.community-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--sp-4);
}

.community-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: var(--sp-5);
  transition: all var(--duration) var(--ease);
}

.community-card:hover {
  border-color: var(--border);
  transform: translateY(-1px);
}

.community-card h4 {
  margin-bottom: var(--sp-2);
  font-size: 0.92rem;
}

.community-card h4 a { color: var(--accent); }

.community-card p {
  color: var(--text-muted);
  font-size: 0.82rem;
  line-height: 1.5;
}

/* ── Section Headers ───────────────────────────────────── */
.section-header {
  margin-bottom: var(--sp-6);
}

.section-header h2 {
  margin-bottom: var(--sp-2);
}

.section-header p {
  color: var(--text-secondary);
  max-width: 600px;
  line-height: 1.7;
}

/* ── Surfaces / Building Blocks / Use Cases Grids ──────── */
.surface-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: var(--sp-5);
  transition: all var(--duration) var(--ease);
}

.surface-card:hover {
  border-color: var(--border);
}

.surface-card h4 { margin-bottom: var(--sp-2); }

.surface-card p {
  color: var(--text-secondary);
  font-size: 0.85rem;
  line-height: 1.55;
}

/* ── Best Practices ────────────────────────────────────── */
.practices-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: var(--sp-4);
}

.practice-item {
  display: flex; align-items: flex-start; gap: var(--sp-3);
  padding: var(--sp-4);
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
}

.practice-item .practice-icon {
  width: 28px; height: 28px;
  background: var(--accent-bg);
  color: var(--accent);
  border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
  font-size: 0.85rem;
}

.practice-item h4 {
  font-size: 0.9rem;
  margin-bottom: var(--sp-1);
}

.practice-item p {
  color: var(--text-muted);
  font-size: 0.8rem;
  line-height: 1.5;
}

/* ── Footer ────────────────────────────────────────────── */
.site-footer {
  border-top: 1px solid var(--border-subtle);
  padding: var(--sp-10) 0 var(--sp-8);
  margin-top: var(--sp-12);
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--sp-6);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: var(--sp-8);
  margin-bottom: var(--sp-8);
}

.footer-brand {
  font-weight: 800;
  font-size: 1rem;
  margin-bottom: var(--sp-3);
  display: flex; align-items: center; gap: var(--sp-2);
}

.footer-brand .brand-icon {
  width: 20px; height: 20px;
  background: var(--accent);
  border-radius: 4px;
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 11px; font-weight: 900; color: var(--bg-deep);
}

.footer-brand p {
  color: var(--text-muted);
  font-size: 0.82rem;
  line-height: 1.6;
  max-width: 280px;
}

.footer-col h5 {
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  margin-bottom: var(--sp-3);
  font-weight: 600;
}

.footer-col ul {
  list-style: none;
}

.footer-col ul li {
  margin-bottom: var(--sp-2);
}

.footer-col ul li a {
  color: var(--text-secondary);
  font-size: 0.85rem;
}

.footer-col ul li a:hover {
  color: var(--text);
}

.footer-bottom {
  border-top: 1px solid var(--border-subtle);
  padding-top: var(--sp-5);
  display: flex; justify-content: space-between; align-items: center;
}

.footer-bottom p {
  color: var(--text-muted);
  font-size: 0.78rem;
}

/* ── Agents Protocol Diagram ───────────────────────────── */
.protocol-diagram {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--sp-4);
  margin: var(--sp-6) 0;
}

.protocol-actor {
  text-align: center;
  padding: var(--sp-5);
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
}

.protocol-actor .actor-icon {
  width: 48px; height: 48px;
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  margin: 0 auto var(--sp-3);
  font-size: 1.3rem;
  font-weight: 700;
}

.protocol-actor .actor-icon.agent { background: oklch(25% 0.06 170); color: var(--accent); }
.protocol-actor .actor-icon.merchant { background: oklch(22% 0.06 255); color: var(--accent-blue); }
.protocol-actor .actor-icon.cp { background: oklch(22% 0.06 300); color: oklch(72% 0.16 300); }
.protocol-actor .actor-icon.psp { background: oklch(25% 0.07 60); color: oklch(75% 0.16 60); }

.protocol-actor h4 { margin-bottom: var(--sp-1); font-size: 0.95rem; }
.protocol-actor p { color: var(--text-muted); font-size: 0.8rem; }

/* ── Status Badge ──────────────────────────────────────── */
.status-badge {
  display: inline-flex; align-items: center; gap: var(--sp-1);
  font-size: 0.75rem; font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 3px 10px;
  border-radius: 20px;
  background: oklch(25% 0.07 60 / 0.5);
  color: oklch(75% 0.16 60);
}

/* ── Support Cards ─────────────────────────────────────── */
.support-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--sp-4);
}

.support-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: var(--sp-5);
}

.support-card h4 {
  margin-bottom: var(--sp-2);
}

.support-card ul {
  list-style: none;
}

.support-card ul li {
  padding: var(--sp-1) 0;
  color: var(--text-secondary);
  font-size: 0.88rem;
}

.support-card ul li a { color: var(--text-secondary); }
.support-card ul li a:hover { color: var(--accent); }

/* ── Theme / Headless Sections ─────────────────────────── */
.split-section {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--sp-8);
  margin-bottom: var(--sp-10);
}

.feature-list {
  list-style: none;
}

.feature-list li {
  padding: var(--sp-3) 0;
  border-bottom: 1px solid var(--border-subtle);
  display: flex; gap: var(--sp-3);
  align-items: flex-start;
}

.feature-list li:last-child { border-bottom: none; }

.feature-list .feature-dot {
  width: 6px; height: 6px;
  background: var(--accent);
  border-radius: 50%;
  margin-top: 8px;
  flex-shrink: 0;
}

.feature-list h4 {
  font-size: 0.92rem;
  margin-bottom: var(--sp-1);
}

.feature-list p {
  color: var(--text-secondary);
  font-size: 0.85rem;
  line-height: 1.5;
}

/* ── Responsive ────────────────────────────────────────── */
@media (max-width: 1024px) {
  .product-cards { grid-template-columns: 1fr; }
  .cards-grid-3 { grid-template-columns: repeat(2, 1fr); }
  .community-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .protocol-diagram { grid-template-columns: repeat(2, 1fr); }
  .split-section { grid-template-columns: 1fr; gap: var(--sp-6); }
  .launch-cards { grid-template-columns: 1fr; }

  .sidebar {
    position: fixed;
    left: 0; top: var(--nav-height);
    z-index: 90;
    background: var(--bg-base);
    transform: translateX(-100%);
    transition: transform var(--duration) var(--ease);
    width: var(--sidebar-width);
    padding: var(--sp-6) var(--sp-4);
    height: calc(100vh - var(--nav-height));
  }

  .sidebar:not(.collapsed) {
    transform: translateX(0);
  }

  .sidebar.collapsed {
    width: var(--sidebar-width);
    padding: var(--sp-6) var(--sp-4);
    overflow: auto;
  }

  .sidebar-toggle {
    display: none;
  }
}

@media (max-width: 768px) {
  :root { --sp-6: 16px; --sp-8: 24px; --sp-12: 48px; }

  .nav-links { display: none; }
  .nav-links.open {
    display: flex; flex-direction: column;
    position: absolute; top: var(--nav-height); left: 0; right: 0;
    background: var(--bg-base);
    border-bottom: 1px solid var(--border);
    padding: var(--sp-4) var(--sp-6);
    gap: var(--sp-1);
  }

  .mobile-menu-btn { display: flex; }

  .cards-grid, .cards-grid-3, .cards-grid-2 { grid-template-columns: 1fr; }
  .community-grid { grid-template-columns: 1fr; }
  .launch-cards { grid-template-columns: 1fr; }
  .support-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: var(--sp-5); }
  .protocol-diagram { grid-template-columns: 1fr 1fr; }
  .hero { padding: var(--sp-8) 0 var(--sp-6); }

  .main-content {
    padding: var(--sp-5) var(--sp-4) var(--sp-8);
  }
}

@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
  .protocol-diagram { grid-template-columns: 1fr; }
  .hero-ctas { flex-direction: column; }
  .hero-ctas .btn { width: 100%; justify-content: center; }
}

/* ── Utility ───────────────────────────────────────────── */
.mt-4 { margin-top: var(--sp-4); }
.mt-6 { margin-top: var(--sp-6); }
.mt-8 { margin-top: var(--sp-8); }
.mb-4 { margin-bottom: var(--sp-4); }
.mb-6 { margin-bottom: var(--sp-6); }
.mb-8 { margin-bottom: var(--sp-8); }
.mb-10 { margin-bottom: var(--sp-10); }
.mb-12 { margin-bottom: var(--sp-12); }

.text-accent { color: var(--accent); }
.text-blue { color: var(--accent-blue); }
.text-muted { color: var(--text-muted); }
.text-secondary { color: var(--text-secondary); }

raw_arguments.content:
/* CommerceForge Dev Docs — Design System */

/* ── Reset & Base ──────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  /* OKLCH Color System */
  --bg-deep:     oklch(13% 0.015 260);
  --bg-base:     oklch(15% 0.018 260);
  --bg-surface:  oklch(19% 0.018 260);
  --bg-raised:   oklch(22% 0.018 260);
  --border:      oklch(28% 0.018 260);
  --border-subtle: oklch(24% 0.015 260);

  --accent:      oklch(78% 0.17 170);
  --accent-dim:  oklch(55% 0.12 170);
  --accent-bg:   oklch(22% 0.06 170);
  --accent-blue: oklch(65% 0.18 255);
  --accent-blue-dim: oklch(50% 0.12 255);

  --text:        oklch(95% 0.005 260);
  --text-secondary: oklch(68% 0.012 260);
  --text-muted:  oklch(50% 0.012 260);

  /* Typography */
  --font-sans: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', ui-monospace, monospace;

  /* Spacing Scale */
  --sp-1: 4px;  --sp-2: 8px;  --sp-3: 12px;  --sp-4: 16px;
  --sp-5: 20px; --sp-6: 24px; --sp-7: 32px;  --sp-8: 40px;
  --sp-9: 48px; --sp-10: 64px; --sp-11: 80px; --sp-12: 96px;

  /* Radius */
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;

  /* Transitions */
  --ease: cubic-bezier(0.4, 0, 0.2, 1);
  --duration: 200ms;

  /* Layout */
  --max-width: 1200px;
  --sidebar-width: 260px;
  --nav-height: 60px;
}

html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; }

body {
  font-family: var(--font-sans);
  background: var(--bg-deep);
  color: var(--text);
  line-height: 1.6;
  font-size: 15px;
  min-height: 100vh;
}

a { color: var(--accent); text-decoration: none; transition: color var(--duration) var(--ease); }
a:hover { color: oklch(85% 0.2 170); }

h1, h2, h3, h4 { line-height: 1.2; font-weight: 700; color: var(--text); }
h1 { font-size: clamp(2rem, 4vw, 2.75rem); letter-spacing: -0.03em; }
h2 { font-size: clamp(1.5rem, 3vw, 2rem); letter-spacing: -0.02em; }
h3 { font-size: 1.15rem; letter-spacing: -0.01em; }
h4 { font-size: 1rem; }

/* ── Top Navigation ────────────────────────────────────── */
.top-nav {
  position: sticky; top: 0; z-index: 100;
  height: var(--nav-height);
  background: oklch(13% 0.015 260 / 0.85);
  backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border-subtle);
  display: flex; align-items: center;
  padding: 0 var(--sp-6);
}

.nav-inner {
  max-width: var(--max-width);
  width: 100%;
  margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between;
}

.nav-brand {
  font-weight: 800; font-size: 1.05rem;
  color: var(--text);
  display: flex; align-items: center; gap: var(--sp-2);
  white-space: nowrap;
}

.nav-brand .brand-icon {
  width: 24px; height: 24px;
  background: var(--accent);
  border-radius: var(--radius-sm);
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 14px; font-weight: 900; color: var(--bg-deep);
}

.nav-links {
  display: flex; align-items: center; gap: var(--sp-6);
  list-style: none;
}

.nav-links a {
  color: var(--text-secondary);
  font-size: 0.9rem;
  font-weight: 500;
  transition: color var(--duration) var(--ease);
  padding: var(--sp-2) 0;
  position: relative;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--text);
}

.nav-links a.active::after {
  content: '';
  position: absolute; bottom: -2px; left: 0; right: 0;
  height: 2px;
  background: var(--accent);
  border-radius: 1px;
}

.nav-utils {
  display: flex; align-items: center; gap: var(--sp-4);
}

.nav-utils .search-btn {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  color: var(--text-muted);
  padding: var(--sp-1) var(--sp-3);
  font-size: 0.82rem;
  cursor: pointer;
  display: flex; align-items: center; gap: var(--sp-2);
  transition: border-color var(--duration) var(--ease);
}

.nav-utils .search-btn:hover { border-color: var(--accent-dim); }

.nav-utils .search-btn kbd {
  background: var(--bg-raised);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 1px 5px;
  font-family: var(--font-mono);
  font-size: 0.72rem;
  color: var(--text-muted);
}

.login-btn {
  color: var(--text-secondary) !important;
  font-size: 0.9rem !important;
  font-weight: 500 !important;
}

.mobile-menu-btn {
  display: none;
  background: none; border: none; color: var(--text); cursor: pointer;
  padding: var(--sp-2);
}

/* ── Page Layout ───────────────────────────────────────── */
.page-container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--sp-6);
}

.page-container.wide {
  max-width: 1400px;
}

/* Layout with sidebar */
.layout-with-sidebar {
  display: flex;
  max-width: 1400px;
  margin: 0 auto;
  min-height: calc(100vh - var(--nav-height));
}

.sidebar {
  width: var(--sidebar-width);
  flex-shrink: 0;
  border-right: 1px solid var(--border-subtle);
  padding: var(--sp-6) var(--sp-4);
  position: sticky;
  top: var(--nav-height);
  height: calc(100vh - var(--nav-height));
  overflow-y: auto;
  transition: width var(--duration) var(--ease), padding var(--duration) var(--ease);
}

.sidebar.collapsed {
  width: 0;
  padding: var(--sp-6) 0;
  overflow: hidden;
  border-right: none;
}

.sidebar-toggle {
  position: absolute;
  right: -14px;
  top: var(--sp-8);
  width: 28px; height: 28px;
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: 50%;
  color: var(--text-secondary);
  cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  font-size: 14px;
  z-index: 10;
  transition: all var(--duration) var(--ease);
}

.sidebar-toggle:hover {
  background: var(--bg-raised);
  color: var(--text);
  border-color: var(--accent-dim);
}

.sidebar-nav { list-style: none; }

.sidebar-nav li a {
  display: block;
  padding: var(--sp-2) var(--sp-3);
  color: var(--text-secondary);
  font-size: 0.88rem;
  border-radius: var(--radius-sm);
  transition: all var(--duration) var(--ease);
  margin-bottom: 2px;
}

.sidebar-nav li a:hover {
  color: var(--text);
  background: var(--bg-surface);
}

.sidebar-nav li a.active {
  color: var(--accent);
  background: var(--accent-bg);
}

.sidebar-label {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  padding: var(--sp-3) var(--sp-3) var(--sp-1);
  font-weight: 600;
}

.main-content {
  flex: 1;
  min-width: 0;
  padding: var(--sp-8) var(--sp-8) var(--sp-12);
}

/* ── Hero Section ──────────────────────────────────────── */
.hero {
  padding: var(--sp-12) 0 var(--sp-10);
  max-width: 720px;
}

.hero.narrow { max-width: 600px; }

.hero h1 {
  margin-bottom: var(--sp-4);
  background: linear-gradient(135deg, var(--text) 0%, var(--text-secondary) 100%);
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero p {
  font-size: 1.08rem;
  color: var(--text-secondary);
  line-height: 1.7;
  margin-bottom: var(--sp-6);
}

.hero-ctas {
  display: flex; flex-wrap: wrap; gap: var(--sp-3);
}

/* ── Buttons ───────────────────────────────────────────── */
.btn {
  display: inline-flex; align-items: center; gap: var(--sp-2);
  padding: var(--sp-2) var(--sp-5);
  border-radius: var(--radius-md);
  font-family: var(--font-sans);
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: all var(--duration) var(--ease);
  white-space: nowrap;
}

.btn-primary {
  background: var(--accent);
  color: var(--bg-deep);
}

.btn-primary:hover {
  background: oklch(82% 0.19 170);
  color: var(--bg-deep);
}

.btn-secondary {
  background: var(--bg-surface);
  color: var(--text);
  border: 1px solid var(--border);
}

.btn-secondary:hover {
  border-color: var(--accent-dim);
  background: var(--bg-raised);
}

.btn-ghost {
  background: transparent;
  color: var(--accent);
  padding: var(--sp-2) var(--sp-3);
}

.btn-ghost:hover {
  background: var(--accent-bg);
}

.btn-arrow::after {
  content: '→';
  transition: transform var(--duration) var(--ease);
}

.btn-arrow:hover::after {
  transform: translateX(3px);
}

/* ── Cards ─────────────────────────────────────────────── */
.card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: var(--sp-6);
  transition: all var(--duration) var(--ease);
  position: relative;
}

.card:hover {
  border-color: var(--border);
  transform: translateY(-2px);
  box-shadow: 0 8px 32px oklch(0% 0 0 / 0.3);
}

.card-icon {
  width: 40px; height: 40px;
  border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  font-size: 1.2rem;
  margin-bottom: var(--sp-4);
}

.card-icon.green { background: oklch(25% 0.06 170); color: var(--accent); }
.card-icon.blue { background: oklch(22% 0.06 255); color: var(--accent-blue); }
.card-icon.purple { background: oklch(22% 0.06 300); color: oklch(72% 0.16 300); }
.card-icon.orange { background: oklch(25% 0.07 60); color: oklch(75% 0.16 60); }
.card-icon.red { background: oklch(22% 0.06 20); color: oklch(68% 0.16 20); }
.card-icon.cyan { background: oklch(22% 0.06 195); color: oklch(72% 0.14 195); }

.card h3 {
  margin-bottom: var(--sp-2);
  font-size: 1.05rem;
}

.card p {
  color: var(--text-secondary);
  font-size: 0.9rem;
  line-height: 1.6;
  margin-bottom: var(--sp-4);
}

.card .card-cta {
  font-size: 0.88rem;
  font-weight: 600;
}

/* Cards grid */
.cards-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--sp-5);
}

.cards-grid-3 {
  grid-template-columns: repeat(3, 1fr);
}

.cards-grid-2 {
  grid-template-columns: repeat(2, 1fr);
}

/* ── Product Cards (Home) ──────────────────────────────── */
.product-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--sp-5);
  margin-bottom: var(--sp-12);
}

.product-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: var(--sp-7);
  transition: all var(--duration) var(--ease);
  position: relative;
  overflow: hidden;
}

.product-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  border-radius: var(--radius-lg) var(--radius-lg) 0 0;
}

.product-card.apps::before { background: var(--accent); }
.product-card.storefronts::before { background: var(--accent-blue); }
.product-card.agents::before { background: oklch(72% 0.16 300); }

.product-card:hover {
  border-color: var(--border);
  transform: translateY(-3px);
  box-shadow: 0 12px 40px oklch(0% 0 0 / 0.35);
}

.product-card .product-label {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 700;
  margin-bottom: var(--sp-3);
}

.product-card.apps .product-label { color: var(--accent); }
.product-card.storefronts .product-label { color: var(--accent-blue); }
.product-card.agents .product-label { color: oklch(72% 0.16 300); }

.product-card h3 {
  font-size: 1.25rem;
  margin-bottom: var(--sp-3);
}

.product-card p {
  color: var(--text-secondary);
  font-size: 0.92rem;
  line-height: 1.65;
  margin-bottom: var(--sp-5);
}

.product-card .card-cta {
  font-weight: 600; font-size: 0.9rem;
}

.product-card.apps .card-cta { color: var(--accent); }
.product-card.storefronts .card-cta { color: var(--accent-blue); }
.product-card.agents .card-cta { color: oklch(72% 0.16 300); }

/* ── CLI / Accordion Section ───────────────────────────── */
.cli-section {
  margin-bottom: var(--sp-12);
}

.cli-section > h2 {
  margin-bottom: var(--sp-3);
}

.cli-section > p {
  color: var(--text-secondary);
  max-width: 640px;
  line-height: 1.7;
  margin-bottom: var(--sp-7);
}

.accordion {
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--bg-surface);
}

.accordion-item {
  border-bottom: 1px solid var(--border-subtle);
}

.accordion-item:last-child { border-bottom: none; }

.accordion-header {
  width: 100%;
  background: none; border: none;
  color: var(--text);
  padding: var(--sp-4) var(--sp-5);
  font-family: var(--font-sans);
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  display: flex; align-items: center; justify-content: space-between;
  transition: background var(--duration) var(--ease);
}

.accordion-header:hover {
  background: var(--bg-raised);
}

.accordion-header .chevron {
  transition: transform var(--duration) var(--ease);
  color: var(--text-muted);
  font-size: 0.8rem;
}

.accordion-item.open .accordion-header .chevron {
  transform: rotate(180deg);
}

.accordion-item.open .accordion-header {
  color: var(--accent);
}

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 300ms var(--ease);
}

.accordion-body-inner {
  padding: 0 var(--sp-5) var(--sp-5);
}

.step-list {
  list-style: none;
  counter-reset: steps;
}

.step-list li {
  counter-increment: steps;
  padding: var(--sp-3) 0;
  color: var(--text-secondary);
  font-size: 0.9rem;
  display: flex; gap: var(--sp-3);
  line-height: 1.6;
}

.step-list li::before {
  content: counter(steps);
  min-width: 24px; height: 24px;
  background: var(--accent-bg);
  color: var(--accent);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 0.75rem;
  font-weight: 700;
  flex-shrink: 0;
  margin-top: 2px;
}

/* Tabbed code blocks */
.code-tabs {
  margin-top: var(--sp-4);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
}

.code-tabs-header {
  display: flex;
  background: var(--bg-raised);
  border-bottom: 1px solid var(--border-subtle);
}

.code-tab {
  padding: var(--sp-2) var(--sp-4);
  background: none; border: none;
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 0.82rem;
  cursor: pointer;
  position: relative;
  transition: color var(--duration) var(--ease);
}

.code-tab:hover { color: var(--text-secondary); }

.code-tab.active {
  color: var(--accent);
}

.code-tab.active::after {
  content: '';
  position: absolute; bottom: 0; left: 0; right: 0;
  height: 2px;
  background: var(--accent);
}

.code-panel {
  display: none;
  padding: var(--sp-4);
}

.code-panel.active { display: block; }

.code-block {
  background: var(--bg-deep);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: var(--sp-4) var(--sp-5);
  font-family: var(--font-mono);
  font-size: 0.88rem;
  line-height: 1.7;
  color: var(--text);
  overflow-x: auto;
  margin-top: var(--sp-3);
}

.code-block .prompt { color: var(--accent); user-select: none; }
.code-block .flag { color: oklch(72% 0.16 300); }
.code-block .pkg { color: var(--accent-blue); }

/* ── Launch CTA Section ────────────────────────────────── */
.launch-section {
  margin-bottom: var(--sp-12);
}

.launch-cards {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--sp-5);
}

.launch-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: var(--sp-7);
  transition: all var(--duration) var(--ease);
}

.launch-card:hover {
  border-color: var(--border);
}

.launch-card h3 { margin-bottom: var(--sp-3); }

.launch-card p {
  color: var(--text-secondary);
  font-size: 0.92rem;
  line-height: 1.65;
  margin-bottom: var(--sp-4);
}

/* ── Community Section ─────────────────────────────────── */
.community-section {
  margin-bottom: var(--sp-12);
}

.community-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--sp-4);
}

.community-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: var(--sp-5);
  transition: all var(--duration) var(--ease);
}

.community-card:hover {
  border-color: var(--border);
  transform: translateY(-1px);
}

.community-card h4 {
  margin-bottom: var(--sp-2);
  font-size: 0.92rem;
}

.community-card h4 a { color: var(--accent); }

.community-card p {
  color: var(--text-muted);
  font-size: 0.82rem;
  line-height: 1.5;
}

/* ── Section Headers ───────────────────────────────────── */
.section-header {
  margin-bottom: var(--sp-6);
}

.section-header h2 {
  margin-bottom: var(--sp-2);
}

.section-header p {
  color: var(--text-secondary);
  max-width: 600px;
  line-height: 1.7;
}

/* ── Surfaces / Building Blocks / Use Cases Grids ──────── */
.surface-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: var(--sp-5);
  transition: all var(--duration) var(--ease);
}

.surface-card:hover {
  border-color: var(--border);
}

.surface-card h4 { margin-bottom: var(--sp-2); }

.surface-card p {
  color: var(--text-secondary);
  font-size: 0.85rem;
  line-height: 1.55;
}

/* ── Best Practices ────────────────────────────────────── */
.practices-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: var(--sp-4);
}

.practice-item {
  display: flex; align-items: flex-start; gap: var(--sp-3);
  padding: var(--sp-4);
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
}

.practice-item .practice-icon {
  width: 28px; height: 28px;
  background: var(--accent-bg);
  color: var(--accent);
  border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
  font-size: 0.85rem;
}

.practice-item h4 {
  font-size: 0.9rem;
  margin-bottom: var(--sp-1);
}

.practice-item p {
  color: var(--text-muted);
  font-size: 0.8rem;
  line-height: 1.5;
}

/* ── Footer ────────────────────────────────────────────── */
.site-footer {
  border-top: 1px solid var(--border-subtle);
  padding: var(--sp-10) 0 var(--sp-8);
  margin-top: var(--sp-12);
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--sp-6);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: var(--sp-8);
  margin-bottom: var(--sp-8);
}

.footer-brand {
  font-weight: 800;
  font-size: 1rem;
  margin-bottom: var(--sp-3);
  display: flex; align-items: center; gap: var(--sp-2);
}

.footer-brand .brand-icon {
  width: 20px; height: 20px;
  background: var(--accent);
  border-radius: 4px;
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 11px; font-weight: 900; color: var(--bg-deep);
}

.footer-brand p {
  color: var(--text-muted);
  font-size: 0.82rem;
  line-height: 1.6;
  max-width: 280px;
}

.footer-col h5 {
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  margin-bottom: var(--sp-3);
  font-weight: 600;
}

.footer-col ul {
  list-style: none;
}

.footer-col ul li {
  margin-bottom: var(--sp-2);
}

.footer-col ul li a {
  color: var(--text-secondary);
  font-size: 0.85rem;
}

.footer-col ul li a:hover {
  color: var(--text);
}

.footer-bottom {
  border-top: 1px solid var(--border-subtle);
  padding-top: var(--sp-5);
  display: flex; justify-content: space-between; align-items: center;
}

.footer-bottom p {
  color: var(--text-muted);
  font-size: 0.78rem;
}

/* ── Agents Protocol Diagram ───────────────────────────── */
.protocol-diagram {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--sp-4);
  margin: var(--sp-6) 0;
}

.protocol-actor {
  text-align: center;
  padding: var(--sp-5);
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
}

.protocol-actor .actor-icon {
  width: 48px; height: 48px;
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  margin: 0 auto var(--sp-3);
  font-size: 1.3rem;
  font-weight: 700;
}

.protocol-actor .actor-icon.agent { background: oklch(25% 0.06 170); color: var(--accent); }
.protocol-actor .actor-icon.merchant { background: oklch(22% 0.06 255); color: var(--accent-blue); }
.protocol-actor .actor-icon.cp { background: oklch(22% 0.06 300); color: oklch(72% 0.16 300); }
.protocol-actor .actor-icon.psp { background: oklch(25% 0.07 60); color: oklch(75% 0.16 60); }

.protocol-actor h4 { margin-bottom: var(--sp-1); font-size: 0.95rem; }
.protocol-actor p { color: var(--text-muted); font-size: 0.8rem; }

/* ── Status Badge ──────────────────────────────────────── */
.status-badge {
  display: inline-flex; align-items: center; gap: var(--sp-1);
  font-size: 0.75rem; font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 3px 10px;
  border-radius: 20px;
  background: oklch(25% 0.07 60 / 0.5);
  color: oklch(75% 0.16 60);
}

/* ── Support Cards ─────────────────────────────────────── */
.support-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--sp-4);
}

.support-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: var(--sp-5);
}

.support-card h4 {
  margin-bottom: var(--sp-2);
}

.support-card ul {
  list-style: none;
}

.support-card ul li {
  padding: var(--sp-1) 0;
  color: var(--text-secondary);
  font-size: 0.88rem;
}

.support-card ul li a { color: var(--text-secondary); }
.support-card ul li a:hover { color: var(--accent); }

/* ── Theme / Headless Sections ─────────────────────────── */
.split-section {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--sp-8);
  margin-bottom: var(--sp-10);
}

.feature-list {
  list-style: none;
}

.feature-list li {
  padding: var(--sp-3) 0;
  border-bottom: 1px solid var(--border-subtle);
  display: flex; gap: var(--sp-3);
  align-items: flex-start;
}

.feature-list li:last-child { border-bottom: none; }

.feature-list .feature-dot {
  width: 6px; height: 6px;
  background: var(--accent);
  border-radius: 50%;
  margin-top: 8px;
  flex-shrink: 0;
}

.feature-list h4 {
  font-size: 0.92rem;
  margin-bottom: var(--sp-1);
}

.feature-list p {
  color: var(--text-secondary);
  font-size: 0.85rem;
  line-height: 1.5;
}

/* ── Responsive ────────────────────────────────────────── */
@media (max-width: 1024px) {
  .product-cards { grid-template-columns: 1fr; }
  .cards-grid-3 { grid-template-columns: repeat(2, 1fr); }
  .community-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .protocol-diagram { grid-template-columns: repeat(2, 1fr); }
  .split-section { grid-template-columns: 1fr; gap: var(--sp-6); }
  .launch-cards { grid-template-columns: 1fr; }

  .sidebar {
    position: fixed;
    left: 0; top: var(--nav-height);
    z-index: 90;
    background: var(--bg-base);
    transform: translateX(-100%);
    transition: transform var(--duration) var(--ease);
    width: var(--sidebar-width);
    padding: var(--sp-6) var(--sp-4);
    height: calc(100vh - var(--nav-height));
  }

  .sidebar:not(.collapsed) {
    transform: translateX(0);
  }

  .sidebar.collapsed {
    width: var(--sidebar-width);
    padding: var(--sp-6) var(--sp-4);
    overflow: auto;
  }

  .sidebar-toggle {
    display: none;
  }
}

@media (max-width: 768px) {
  :root { --sp-6: 16px; --sp-8: 24px; --sp-12: 48px; }

  .nav-links { display: none; }
  .nav-links.open {
    display: flex; flex-direction: column;
    position: absolute; top: var(--nav-height); left: 0; right: 0;
    background: var(--bg-base);
    border-bottom: 1px solid var(--border);
    padding: var(--sp-4) var(--sp-6);
    gap: var(--sp-1);
  }

  .mobile-menu-btn { display: flex; }

  .cards-grid, .cards-grid-3, .cards-grid-2 { grid-template-columns: 1fr; }
  .community-grid { grid-template-columns: 1fr; }
  .launch-cards { grid-template-columns: 1fr; }
  .support-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: var(--sp-5); }
  .protocol-diagram { grid-template-columns: 1fr 1fr; }
  .hero { padding: var(--sp-8) 0 var(--sp-6); }

  .main-content {
    padding: var(--sp-5) var(--sp-4) var(--sp-8);
  }
}

@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
  .protocol-diagram { grid-template-columns: 1fr; }
  .hero-ctas { flex-direction: column; }
  .hero-ctas .btn { width: 100%; justify-content: center; }
}

/* ── Utility ───────────────────────────────────────────── */
.mt-4 { margin-top: var(--sp-4); }
.mt-6 { margin-top: var(--sp-6); }
.mt-8 { margin-top: var(--sp-8); }
.mb-4 { margin-bottom: var(--sp-4); }
.mb-6 { margin-bottom: var(--sp-6); }
.mb-8 { margin-bottom: var(--sp-8); }
.mb-10 { margin-bottom: var(--sp-10); }
.mb-12 { margin-bottom: var(--sp-12); }

.text-accent { color: var(--accent); }
.text-blue { color: var(--accent-blue); }
.text-muted { color: var(--text-muted); }
.text-secondary { color: var(--text-secondary); }
